import { getAnnotation } from '../../annotation/annotationState.js';
import { getSegmentation } from '../getSegmentation.js';
import interpolateSegmentPoints from '../../../utilities/planarFreehandROITool/interpolation/interpolateSegmentPoints.js';
import { utilities as cornerstoneUtilities } from '@cornerstonejs/core';
const cs3dLogger = cornerstoneUtilities.logger.toolsLog.getLogger('stateManagement.segmentation.utilities.smoothContours');
export default function smoothContours(segmentationId, segmentIndex, options = { knotsRatioPercentage: 30 }) {
    const segmentation = getSegmentation(segmentationId);
    if (!segmentation) {
        cs3dLogger.warn(`Invalid segmentation given ${segmentationId}`);
        return;
    }
    if (!segmentation.representationData.Contour) {
        cs3dLogger.warn(`No contour representation found for segmentation ${segmentationId}`);
        return;
    }
    const contourRepresentationData = segmentation.representationData
        .Contour;
    const { annotationUIDsMap } = contourRepresentationData;
    if (!annotationUIDsMap) {
        cs3dLogger.warn(`No contours found for segmentation ${segmentationId}`);
        return;
    }
    if (!annotationUIDsMap.has(segmentIndex)) {
        cs3dLogger.warn(`Error extracting contour data from segment ${segmentIndex} in segmentation ${segmentationId}`);
        return;
    }
    const annotationList = annotationUIDsMap.get(segmentIndex);
    annotationList.forEach((annotationUID) => {
        const annotation = getAnnotation(annotationUID);
        if (!annotation) {
            return;
        }
        const polyline = annotation.data.contour.polyline;
        if (!polyline || polyline.length < 3) {
            return;
        }
        const smoothedPolyline = interpolateSegmentPoints(polyline, 0, polyline.length - 1, options.knotsRatioPercentage);
        annotation.data.contour.polyline = smoothedPolyline;
    });
}
